package p

// Cyclomatic12 has McCabe cyclomatic complexity 12, over the HISS-04 cap of 10.
func Cyclomatic12(total int) int {
	if total > 0 {
		total++
	}
	if total > 1 {
		total++
	}
	if total > 2 {
		total++
	}
	if total > 3 {
		total++
	}
	if total > 4 {
		total++
	}
	if total > 5 {
		total++
	}
	if total > 6 {
		total++
	}
	if total > 7 {
		total++
	}
	if total > 8 {
		total++
	}
	if total > 9 {
		total++
	}
	if total > 10 {
		total++
	}
	return total
}
